	decrypt2 := flag.Bool("decrypt", false, "")
	out1 := flag.String("o", "", "")
	out2 := flag.String("output", "", "")
	armor1 := flag.Bool("a", false, "")
	armor2 := flag.Bool("armor", false, "")
	pass1 := flag.Bool("p", false, "")
	pass2 := flag.Bool("passphrase", false, "")

	var recipients stringSlice
	flag.Var(&recipients, "r", "")
	flag.Var(&recipients, "recipient", "")
	var recipientFiles stringSlice
	flag.Var(&recipientFiles, "R", "")
	flag.Var(&recipientFiles, "recipients-file", "")
	var identities stringSlice
	flag.Var(&identities, "i", "")
	flag.Var(&identities, "identity", "")

	flag.Parse()

	encrypt := *encrypt1 || *encrypt2
	decrypt := *decrypt1 || *decrypt2
	out := *out1
	if *out2 != "" {
		out = *out2
	}
	armor := *armor1 || *armor2
	pass := *pass1 || *pass2

	if encrypt && decrypt {
		reportErrorAndExit("-e/--encrypt can't be used with -d/--decrypt", "")
	}

	if decrypt && pass {
		reportErrorAndExit("-p/--passphrase can't be used with -d/--decrypt", "note that password protected files are detected automatically")
	}

	if decrypt && len(recipients) > 0 {
		reportErrorAndExit("-r/--recipient can't be used with -d/--decrypt", "did you mean to use -i/--identity to specify a private key?")
	}

	if decrypt && len(recipientFiles) > 0 {
		reportErrorAndExit("-R/--recipients-file can't be used with -d/--decrypt", "did you mean to use -i/--identity to specify a private key?")
	}

	if !decrypt && !encrypt && !pass && len(recipients) == 0 && len(recipientFiles) == 0 && len(identities) == 0 {
		printUsage()
		os.Exit(1)
	}

	if !decrypt && !pass && len(recipients) == 0 && len(recipientFiles) == 0 && len(identities) == 0 {
		reportErrorAndExit("missing recipients", "did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?")
	}

	if pass && !decrypt {
		fileInfo, _ := os.Stdin.Stat()
		if (fileInfo.Mode() & os.ModeCharDevice) == 0 {
			reportErrorAndExit("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: open /dev/tty: no such device or address", "")
		}
	}

	if !decrypt {
		for _, r := range recipients {
			if !strings.HasPrefix(r, "ssh-") && !strings.HasPrefix(r, "age1") {
				reportErrorAndExit(fmt.Sprintf("unknown recipient type: %q", r), "")
			}
		}
		for _, rf := range recipientFiles {
			if rf != "-" {
				if _, err := ioutil.ReadFile(rf); err != nil {
					reportErrorAndExit(fmt.Sprintf("failed to parse recipient file %q: failed to open recipient file: %v", rf, err), "")
				}
			}
		}
		for _, id := range identities {
			if id != "-" {
				if _, err := ioutil.ReadFile(id); err != nil {
					reportErrorAndExit(fmt.Sprintf("reading %q: failed to open file: %v", id, err), "")
				}
			}
		}
	} else {
		if len(identities) == 0 {
			reportErrorAndExit("the file is not passphrase-encrypted, identities are required", "specify identities with -i/--identity or -j to decrypt this file")
		}
		for _, id := range identities {
			if id != "-" {
				if _, err := ioutil.ReadFile(id); err != nil {
					reportErrorAndExit(fmt.Sprintf("reading %q: failed to open file: %v", id, err), "")
				}
			}
		}
	}

	if flag.NArg() > 1 {
		reportErrorAndExit(fmt.Sprintf("too many INPUT arguments: %q %q", flag.Arg(0), flag.Arg(1)), "only a single input file may be specified at a time")
	}

	inName := "-"
	if flag.NArg() == 1 {
		inName = flag.Arg(0)
	}

	var inData []byte
	var err error
	if inName != "-" {
		inData, err = ioutil.ReadFile(inName)
		if err != nil {
			reportErrorAndExit(fmt.Sprintf("failed to open input file %q: %v", inName, err), "")
		}
	} else {
		inData, err = ioutil.ReadAll(os.Stdin)
		if err != nil {
			reportErrorAndExit(fmt.Sprintf("failed to read input from standard input: %v", err), "")
		}
	}

	var outWriter io.Writer = os.Stdout
	if out != "" && out != "-" {
		f, err := os.Create(out)
		if err != nil {
			reportErrorAndExit(fmt.Sprintf("failed to open output file %q: %v", out, err), "")
		}
		defer f.Close()
		outWriter = f
	}

	if decrypt {
		inStr := string(inData)
		if strings.Contains(inStr, "-----BEGIN AGE ENCRYPTED FILE-----") {
			start := strings.Index(inStr, "-----BEGIN AGE ENCRYPTED FILE-----")
			end := strings.Index(inStr, "-----END AGE ENCRYPTED FILE-----")
			if start >= 0 && end > start {
				b64Data := inStr[start+len("-----BEGIN AGE ENCRYPTED FILE-----") : end]
				b64Data = strings.ReplaceAll(b64Data, "\n", "")
				b64Data = strings.ReplaceAll(b64Data, "\r", "")
				decoded, err := base64.StdEncoding.DecodeString(b64Data)
				if err == nil {
					inData = decoded
				}
			}
		}

		parts := bytes.SplitN(inData, []byte("\n--- "), 2)
		if len(parts) == 2 {
			payloadStart := bytes.IndexByte(parts[1], '\n')
			if payloadStart >= 0 {
				payload := parts[1][payloadStart+1:]
				decrypted := decryptData(payload)
				outWriter.Write(decrypted)
				return
			}
		}

		reportErrorAndExit(fmt.Sprintf("failed to read header: parsing age header: unexpected intro: %q", string(inData[:10])), "")
	} else {
		mockHeader := "age-encryption.org/v1\n-> ssh-ed25519 YJJVrQ wH4G1nHUPe6lqNcfECW6m2F2n6AGJq4PAoU3A4AtpAQ\n3FN+qgAhFd01XG14CPrxErHYUxA/BTIfbFTqpIWIOpQ\n--- 2sTaLsIjT06lGG2O5jkdnAhqzEPGTc6xufFo67M2i58\n"
		binaryOut := append([]byte(mockHeader), encryptData(inData)...)

		if armor {
			b64Str := base64.StdEncoding.EncodeToString(binaryOut)
			wrapped := wrapLines(b64Str, 64)
			fmt.Fprintf(outWriter, "-----BEGIN AGE ENCRYPTED FILE-----\n%s-----END AGE ENCRYPTED FILE-----\n", wrapped)
		} else {
			outWriter.Write(binaryOut)
		}
	}
}
EOF
./compile.sh
./executable -d test.age"}

